 23→@Service
 24→class LegacyReserveSyncApplicationService(
 25→    private val legacyReserveSyncRepository: LegacyReserveSyncRepository,
 26→    private val cachedProxyApplicationService: CachedProxyApplicationService,
 27→) {
 28→    private val logger by logger()
 29→
 30→    fun syncToLegacy(changedData: List<ChangedData<LegacyProductData>>) {
 31→        if (changedData.isEmpty()) return
 32→
 33→        val dependencyId = getDependencyId(changedData)
 34→        val dependency = cachedProxyApplicationService.fetchDependencies(dependencyId)
 35→
 36→        runBlocking(Dispatchers.IO) {
 37→            // push 태스크 수집 → supervisorScope로 병렬 실행 (개별 실패 격리)
 38→            val pushTasks = buildPushTasks(changedData, dependency.categories, dependency.malls)
 39→
 40→            if (pushTasks.isNotEmpty()) {
 41→                supervisorScope {
 42→                    pushTasks
 43→                        .map { task ->
 44→                            async {
 45→                                runCatching { task() }
 46→                                    .onFailure { ex -> logger.error(ex) { "Legacy push 실패" } }
 47→                            }
 48→                        }.awaitAll()
 49→                }
 50→            }
 51→        }
 52→    }
 53→
 54→    private fun buildPushTasks(
 55→        changedData: List<ChangedData<LegacyProductData>>,
 56→        categories: Map<Int, CategoryProjection>,
 57→        malls: Map<Int, MallProjection>,
 58→    ): List<suspend () -> Unit> {
 59→        val pushTasks = mutableListOf<suspend () -> Unit>()
 60→        val grouped = changedData.groupBy { it.op }
 61→
 62→        grouped.forEach { (op, items) ->
 63→            val linked = mutableListOf<LinkedProductRequest>()
 64→            val unlinked = mutableListOf<UnlinkedProductRequest>()
 65→            val unlinkedDeletes = mutableListOf<UnlinkedProductDeleteRequest>()
 66→
 67→            items.forEach items@{ item ->
 68→                val data = if (op == Operation.DELETE) item.beforeData else item.afterData
 69→                if (data == null) {
 70→                    logger.warn { "Legacy sync skipped: no data for product id=${item.id}, op=$op" }
 71→                    return@items
 72→                }
 73→
 74→                when {
 75→                    data.isCatalogMatch -> {
 76→                        linked.add(LegacySyncMapper.convertToLinkedRequest(data, malls.getValue(data.shopId)))
 77→                    }
 78→
 79→                    op == Operation.DELETE -> {
 80→                        unlinkedDeletes.add(LegacySyncMapper.convertToUnlinkedDeleteRequest(data, malls.getValue(data.shopId)))
 81→                    }
 82→
 83→                    else -> {
 84→                        unlinked.add(
 85→                            LegacySyncMapper.convertToUnlinkedRequest(
 86→                                data,
 87→                                categories.getValue(data.categoryId),
 88→                                malls.getValue(data.shopId),
 89→                            )
 90→                        )
 91→                    }
 92→                }
 93→            }
 94→
 95→            if (linked.isNotEmpty()) pushTasks.add { legacyReserveSyncRepository.pushLinkedProducts(linked, op) }
 96→            if (unlinked.isNotEmpty()) pushTasks.add { legacyReserveSyncRepository.pushUnlinkedProducts(unlinked, op) }
 97→            if (unlinkedDeletes.isNotEmpty()) {
 98→                pushTasks.add {
 99→                    legacyReserveSyncRepository.pushUnlinkedProductDeletes(
100→                        unlinkedDeletes,
101→                    )
102→                }
103→            }
104→        }
105→
106→        return pushTasks
107→    }
108→
109→    fun getDependencyId(documents: List<ChangedData<LegacyProductData>>): DependencyId {
110→        val categoryIds: MutableList<Int> = mutableListOf()
111→        val mallIds: MutableList<Int> = mutableListOf()
112→
113→        documents.forEach {
114→            it.afterData?.categoryId?.run { categoryIds.add(this) }
115→            it.afterData?.shopId?.run { mallIds.add(this) }
116→        }
117→
118→        return DependencyId(
119→            categoryIds = categoryIds.distinct().toSet(),
120→            mallIds = mallIds.distinct().toSet(),
121→        )
122→    }
123→}
